// Tap relays src to dst unchanged, copying into a bounded analyzer
// channel; overflow drops are counted, never applied to the flow.
func Tap(src <-chan Msg, dst chan<- Msg, buf int) (<-chan Msg, *atomic.Uint64) {
    tap := make(chan Msg, buf)
    dropped := new(atomic.Uint64)
    go func() {
        defer close(tap) // close after the last send; drains end the analyzer
        for m := range src {
            select {
            case tap <- m.Clone(): // deep copy; buffered, never blocks
            default:               // documented non-blocking send
                dropped.Add(1)     // explicit overflow policy: drop the copy
            }
            dst <- m // original forwarded, unmodified
        }
        close(dst)
    }()
    return tap, dropped
}
